"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[899],{9233:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>d,contentTitle:()=>r,default:()=>l,frontMatter:()=>o,metadata:()=>s,toc:()=>c});var n=a(4848),i=a(8453);const o={sidebar_position:1},r="Introduction",s={id:"introduction",title:"Introduction",description:"Welcome to the guide for Idiom. Ideally, an application is designed in such a way that users don't need a tutorial, video, or a text-heavy guide to show them how to use it. If they do, that may be a sign that the app is not very user-friendly. Nonetheless, as an application becomes more complex and offers increasingly more features, it may be helpful to have a quick reference to show what features exist and where they can be found. Additionally, there may be a wider range of ways different users engage with the app, and a guide can show people how others are using different features in ways that hadn't previously occurred to them.",source:"@site/docs/introduction.md",sourceDirName:".",slug:"/introduction",permalink:"/docs/introduction",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:1,frontMatter:{sidebar_position:1},sidebar:"tutorialSidebar",next:{title:"Creating your first folder",permalink:"/docs/creating-folders"}},d={},c=[{value:"What is Idiom?",id:"what-is-idiom",level:2},{value:"The Current State",id:"the-current-state",level:2}];function h(e){const t={h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"introduction",children:"Introduction"})}),"\n",(0,n.jsx)(t.p,{children:"Welcome to the guide for Idiom. Ideally, an application is designed in such a way that users don't need a tutorial, video, or a text-heavy guide to show them how to use it. If they do, that may be a sign that the app is not very user-friendly. Nonetheless, as an application becomes more complex and offers increasingly more features, it may be helpful to have a quick reference to show what features exist and where they can be found. Additionally, there may be a wider range of ways different users engage with the app, and a guide can show people how others are using different features in ways that hadn't previously occurred to them."}),"\n",(0,n.jsx)(t.p,{children:"Like the program itself, this guide is a living document and will grow and change alongside Idiom. At the moment, the current set of features doesn't really require a guide, as the app is still quite simple. However, I still thought it would be useful to have a fallback in case how everything works seems clear to me, but somebody else can't make something work as intended."}),"\n",(0,n.jsx)(t.h2,{id:"what-is-idiom",children:"What is Idiom?"}),"\n",(0,n.jsx)(t.p,{children:"Idiom is an app where users can create, store, and practice vocabulary cards for foreign languages. The idea came from two basic impulses. First, physical vocab cards can be tedious to make, hard to organize, and storing them can become messy. Idiom makes this easier and less messy. Second, an app can mimic many of the exercises which can be done with physical cards and offer some additional exercises on top of these."}),"\n",(0,n.jsx)(t.p,{children:"Of course, there may be advantages to handwriting physical cards and sorting them manually. And I am sure there are some exercises which can't be easily done in a digital environment. Idiom simply offers either an alternative way of practicing vocabulary or a complement to what learners already do."}),"\n",(0,n.jsx)(t.h2,{id:"the-current-state",children:"The Current State"}),"\n",(0,n.jsx)(t.p,{children:"So far, storing vocabulary and creating vocab card exercises is all there is. But I am developing other features to help turn this into a 'foreign language self-study suite' where users can create and save their own material and will work well as a complement to formal study or contact with authentic material like texts and audio."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Follow the guide to get started. Or if it all seems obvious, just jump right in."})})]})}function l(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(h,{...e})}):h(e)}},8453:(e,t,a)=>{a.d(t,{R:()=>r,x:()=>s});var n=a(6540);const i={},o=n.createContext(i);function r(e){const t=n.useContext(o);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);